package com.pao.reports.samples;
import com.pao.reports.engine.io.*;import com.pao.reports.engine.model.PreviewJob;import com.pao.reports.engine.render.*;import java.nio.file.*;import javax.imageio.ImageIO;
public final class AllPairsExport{
 public static void main(String[]args)throws Exception{if(args.length!=2)throw new IllegalArgumentException("definition.prepd output-dir");var input=Path.of(args[0]);var out=Path.of(args[1]);Files.createDirectories(out);var doc=new ReportDefinitionIO().read(input);var data=new com.pao.reports.engine.model.ReportData();var shared=input.getParent().resolve("../../src/main/resources/legacy-images/image1-1.jpg").normalize().toAbsolutePath();for(var name:java.util.List.of("image_zoom","image_stretch","image_clip","image_reverse"))data.values.put(name,shared.toString());data.rows.add(new java.util.LinkedHashMap<>(java.util.Map.of("repeat_text","repeat")));var renderer=new ReportRenderer();var image=renderer.render(doc,data,new RenderOptions(144,false,0));ImageIO.write(image,"png",out.resolve("page.png").toFile());if(image.getRGB(0,0)!=0xffffffff)throw new IllegalStateException("report page background is not opaque white");image.flush();new PdfExporter().export(doc,data,out.resolve("page.pdf"));new SvgExporter().export(doc,data,out.resolve("page.svg"));var io=new ReportDefinitionIO();io.write(out.resolve("roundtrip.prepd"),doc);io.write(out.resolve("roundtrip.prepdj"),doc);var job=new PreviewJob();job.name="all-pairs";job.pages.add(new PreviewJob.Page(doc,data,0));var pio=new PreviewJobIO();pio.write(out.resolve("roundtrip.prepe"),job);pio.write(out.resolve("roundtrip.prepej"),job);}
}
